def clean(df):
    issues = []
    # Convert flipper_length_mm to numeric, coerce errors to NaN
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')

    allowed_species = {'Adelie', 'Chinstrap', 'Gentoo'}
    if not all(row['species'] in allowed_species for row in df.itertuples()):
        issues.append({'type': 'label_variant', 'column': 'species'})

    allowed_islands = {'Biscoe', 'Dream', 'Torgersen'}
    if not all(row['island'] in allowed_islands for row in df.itertuples()):
        issues.append({'type': 'label_variant', 'column': 'island'})

    # Check flipper_length_mm for out_of_range
    fl_values = df['flipper_length_mm']
    if (fl_values.isna().any()) or (fl_values < 170).any() or (fl_values > 235).any():
        issues.append({'type': 'out_of_range', 'column': 'flipper_length_mm'})

    # Filter the DataFrame
    valid_df = df[
        (df['species'].isin(allowed_species)) &
        (df['island'].isin(allowed_islands)) &
        (df['flipper_length_mm'].notna()) &
        (df['flipper_length_mm'] >= 170) &
        (df['flipper_length_mm'] <= 235)
    ]
    return valid_df

def answer(df):
    grouped = df.groupby('species')['flipper_length_mm'].mean().reset_index()
    return {row['species']: row['flipper_length_mm'] for row in grouped}
